int read_rm_streams(AVFormatContext *s, AVIOContext *pb, AVStream *st, char *mime) {
    int num_streams, num_mdprs, i, ret;

    num_streams = avio_rb16(pb);
    num_mdprs = avio_rb16(pb);

    if (num_mdprs > 1) {
        av_log(s, AV_LOG_SAMPLE, "Requesting sample data for multiple MDPRs.\n");
    }

    for (i = 0; i < num_mdprs; i++) {
        AVStream *new_st = avformat_new_stream(s, NULL);
        if (!new_st) {
            av_log(s, AV_LOG_ERROR, "Failed to create new stream.\n");
            return AVERROR(ENOMEM);
        }

        ret = avcodec_parameters_copy(new_st->codecpar, st->codecpar);
        if (ret < 0) {
            av_log(s, AV_LOG_ERROR, "Failed to copy codec parameters.\n");
            return ret;
        }

        new_st->codecpar->mime_type = av_strdup(mime);
        if (!new_st->codecpar->mime_type) {
            av_log(s, AV_LOG_ERROR, "Failed to allocate MIME type.\n");
            return AVERROR(ENOMEM);
        }

        ret = avio_read(pb, new_st->codecpar->extradata, new_st->codecpar->extradata_size);
        if (ret < 0) {
            av_log(s, AV_LOG_ERROR, "Failed to read codec data.\n");
            return ret;
        }
    }

    return 0;
}

